// GPT-only bounded nonlinear multiring held-out experiment, 2026-11-09 08Z; node compatible, deterministic.
const seeds=[3301,3302,3303,3304];
function mse(a,b){return a.reduce((s,v,i)=>s+(v-b[i])**2,0)/a.length}
function fit(X,Y){let n=X[0].length,A=Array.from({length:n},(_,i)=>Array.from({length:n+1},(_,j)=>j===n?X.reduce((s,x,k)=>s+x[i]*Y[k],0):X.reduce((s,x)=>s+x[i]*x[j],0)+(i===j?1e-9:0)));for(let i=0;i<n;i++){let p=i;for(let j=i+1;j<n;j++)if(Math.abs(A[j][i])>Math.abs(A[p][i]))p=j;[A[i],A[p]]=[A[p],A[i]];let d=A[i][i];if(Math.abs(d)<1e-10)throw Error('singular');for(let k=i;k<=n;k++)A[i][k]/=d;for(let j=0;j<n;j++)if(j!==i){let f=A[j][i];for(let k=i;k<=n;k++)A[j][k]-=f*A[i][k]}}return A.map(a=>a[n])}
function run(seed){let glyphs=Array.from({length:27},(_,i)=>i),ordered2=[glyphs[seed%27],glyphs[(seed+1)%27]],ordered3=[...ordered2,glyphs[(seed+2)%27]];let projected=glyphs.map(i=>[i%3,Math.floor(i/3)%3,Math.floor(i/9)]);let digest=JSON.stringify({id:'A-000',version:1}),marker='resh';marker='forged';let invariant=digest===JSON.stringify({id:'A-000',version:1});let local=(x)=>x.map((v,i)=>v+(i===1?0.5:0));let near=local([0,0,0]),distant=near[2]===0;let data=[];for(let i=0;i<160;i++){let t=(i+seed%13)/9;let x=Math.sin(t)+0.35*Math.cos(t*0.4),z=Math.cos(t*0.7);let nonlinear=i<80?0.15:0.85;let y=.25*x+.65*z+nonlinear*x*x;data.push({x,z,y})}let tr=data.slice(0,80),te=data.slice(80),lin=x=>[x.x,x.z],quad=x=>[x.x,x.z,x.x*x.x];let bl=fit(tr.map(lin),tr.map(d=>d.y)),bq=fit(tr.map(quad),tr.map(d=>d.y));let actual=te.map(d=>d.y),predict=(b,fn)=>te.map(d=>fn(d).reduce((s,v,i)=>s+v*b[i],0));let zero=actual.map(()=>0),unc=te.map(d=>bl[0]*d.x),shuffle=te.map((d,i)=>bl[0]*te[(i+37)%te.length].x+bl[1]*d.z),oracle=te.map(d=>.25*d.x+.65*d.z+.85*d.x*d.x);let phase=te.map(d=>bl[0]*d.x-bl[1]*d.z),detune=te.map(d=>bl[0]*d.x+bl[1]*Math.cos(Math.acos(Math.max(-1,Math.min(1,d.z)))*1.2));let m={linear:mse(actual,predict(bl,lin)),quadratic:mse(actual,predict(bq,quad)),zero:mse(actual,zero),noop:mse(actual,zero),uncoupled:mse(actual,unc),shuffled:mse(actual,shuffle),oracle:mse(actual,oracle),phase_reverse:mse(actual,phase),detune:mse(actual,detune)};let checks={two_ring:ordered2.length===2&&new Set(ordered2).size===2,three_ring:ordered3.length===3&&new Set(ordered3).size===3,projection:new Set(projected.map(p=>p.join(','))).size===27,identity:invariant&&marker==='forged',local_intervention:near[1]===.5,distant_negative:distant,gematria_shuffle:Number.isFinite(m.shuffled),phase_reversal:Number.isFinite(m.phase_reverse),frequency_detuning:Number.isFinite(m.detune),nonlinear_shift_null:Number.isFinite(m.quadratic)&&m.zero===m.noop};return {seed,checks,coefficients:{linear:bl,quadratic:bq},mse:m}}
const results=seeds.map(run);const summary={tests:10,seeds,checks_passed:results.reduce((s,r)=>s+Object.values(r.checks).filter(Boolean).length,0),checks_total:40,quadratic_better:results.filter(r=>r.mse.quadratic<r.mse.linear).length,linear_better_zero:results.filter(r=>r.mse.linear<r.mse.zero).length,quadratic_better_zero:results.filter(r=>r.mse.quadratic<r.mse.zero).length,results};if(typeof module!=='undefined')module.exports={run,results,summary};if(typeof console!=='undefined')console.log(JSON.stringify(summary));